PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (
 id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL,
 role TEXT NOT NULL DEFAULT 'reader' CHECK(role IN ('reader','editor','admin')),
 bio TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT 'India', language TEXT NOT NULL DEFAULT 'English',
 topics TEXT NOT NULL DEFAULT '[]', theme TEXT NOT NULL DEFAULT 'light', font_size INTEGER NOT NULL DEFAULT 18,
 notifications INTEGER NOT NULL DEFAULT 1, onboarded INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS resets (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS publishers (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, initials TEXT NOT NULL, color TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS articles (
 id INTEGER PRIMARY KEY, author_id INTEGER NOT NULL REFERENCES users(id), publisher_id INTEGER NOT NULL REFERENCES publishers(id),
 title TEXT NOT NULL, excerpt TEXT NOT NULL, body TEXT NOT NULL, category TEXT NOT NULL,
 image TEXT NOT NULL DEFAULT '/images/city.webp', status TEXT NOT NULL CHECK(status IN ('draft','review','published','archived')),
 featured INTEGER NOT NULL DEFAULT 0, is_demo INTEGER NOT NULL DEFAULT 0, views INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_articles_feed ON articles(status,published_at DESC);
CREATE INDEX IF NOT EXISTS idx_articles_category ON articles(category,status);
CREATE TABLE IF NOT EXISTS follows (user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, publisher_id INTEGER REFERENCES publishers(id) ON DELETE CASCADE, PRIMARY KEY(user_id,publisher_id));
CREATE TABLE IF NOT EXISTS collections (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, UNIQUE(user_id,name));
CREATE TABLE IF NOT EXISTS bookmarks (user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE, collection_id INTEGER REFERENCES collections(id) ON DELETE SET NULL, created_at TEXT NOT NULL, PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS likes (user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE, PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS comments (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE, parent_id INTEGER REFERENCES comments(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE, read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS history (user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE, read_at TEXT NOT NULL, PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS app_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
PRAGMA user_version = 1;
